  for j,k in itertools.combinations([x for x in range(1,n+1) if x!=i],2):
   A=list(I);B=list(I);A[i-1]=(j,k,-j,-k,i);B[i-1]=(k,j,-k,-j,i);G.append(tuple(A));Gi.append(tuple(B));names.append(('M',i,j,k))
 return G,Gi,names
